CREATE CATALOG retail_dw COMMENT 'Sample retail sales warehouse for Databricks, covering sales, inventory and customer analytics.';

CREATE SCHEMA retail_dw.staging COMMENT 'Raw landed data from source systems (POS, ERP, CRM).';

CREATE SCHEMA retail_dw.core COMMENT 'Conformed dimensional model: dimensions and facts.';

CREATE SCHEMA retail_dw.mart COMMENT 'Business-facing views for reporting and the semantic layer.';

